const body = $json.body || $json;
return [{
  json: {
    from_email: String(body.from_email || '').trim(),
    subject: String(body.subject || '').trim(),
    body_text: String(body.body_text || '').substring(0, 2000),
    prospect_id: String(body.prospect_id || '').trim(),
    organization_name: String(body.organization_name || '').trim(),
    decision_maker_name: String(body.decision_maker_name || '').trim(),
    nb_personnes: String(body.nb_personnes || '1').trim(),
    secteur: String(body.secteur || '').trim()
  }
}];

const input = $('Normaliser Entrée Agent').first().json;
const raw = $input.all()[0].json;
const rows = Array.isArray(raw) ? raw : [];
const prospect = rows[0] || {};
return [{
  json: {
    ...input,
    organization_name: input.organization_name || prospect.organization_name || '',
    secteur: input.secteur || prospect.sector_guess || '',
    campaign_type: prospect.campaign_type || 'formation_juillet',
    niche_status: prospect.niche_status || ''
  }
}];

const ctx = $('Enrichir Contexte').first().json;
const raw = $input.first().json;
let parsed = {};
try {
  const text = (((raw.choices || [])[0] || {}).message || {}).content || '';
  parsed = JSON.parse(text);
} catch(e) {
  parsed = { reply: '', needs_escalation: true, escalation_reason: 'parse_error' };
}
return [{
  json: {
    ...ctx,
    agent_reply: parsed.reply || '',
    needs_escalation: Boolean(parsed.needs_escalation),
    escalation_reason: parsed.escalation_reason || ''
  }
}];
